class Solution:
    def maximumTime(self, time: str) -> str:
        for h in range(23, -1, -1):
            for m in range(59, -1, -1):
                cand = "%02d:%02d" % (h, m)
                if all(p == "?" or p == c for p, c in zip(time, cand)):
                    return cand
        return ""

