class Solution {
public:
    string maximumTime(string time) {
        for (int h = 23; h >= 0; --h)
            for (int m = 59; m >= 0; --m) {
                string cand = {char('0' + h / 10), char('0' + h % 10), ':',
                               char('0' + m / 10), char('0' + m % 10)};
                bool ok = true;
                for (int i = 0; i < 5 && ok; ++i)
                    ok = time[i] == '?' || time[i] == cand[i];
                if (ok) return cand;
            }
        return "";
    }
};

